#!/usr/bin/env python3
"""Entry for the make.fun bounty news-image-20261125.

"Sum up 25 November's world news in one image" ($100, 50 places,
closes 27 Nov 2026 07:00 WIB). Built by @drac-ximer.

Python 3, standard library only — no network, no dependencies.
Writes the 1024x1024 front page to $MAKEFUN_OUTPUT_DIR/entry.png
(falling back to /output/entry.png, then to the script's own directory
for local runs). The page is embedded as base64 in one line, so runs
are byte-identical. If the embedded data ever failed to decode, a
pure-stdlib fallback draws a minimal title page instead, so the
program still exits 0.
"""

import base64
import binascii
import os
import struct
import sys
import zlib

IMAGE_B64 = ""

# ------------------------------------------------------------------
# Pure-stdlib fallback: a minimal title page (paper, red band, rules).
# Only used if the embedded PNG cannot be decoded.
# ------------------------------------------------------------------

FALLBACK_W, FALLBACK_H = 1024, 1024


def _png_chunk(chunk_type, data):
    chunk = struct.pack(">I", len(data)) + chunk_type + data
    chunk += struct.pack(">I", zlib.crc32(chunk_type + data) & 0xFFFFFFFF)
    return chunk


def _fallback_png():
    """Return PNG bytes for a minimal title page, stdlib only."""
    w, h = FALLBACK_W, FALLBACK_H
    paper = bytes((251, 248, 241))
    red = bytes((185, 28, 28))
    ink = bytes((17, 17, 17))
    navy = bytes((30, 58, 95))
    rows = []
    for y in range(h):
        row = bytearray()
        row.append(0)  # no filter
        for x in range(w):
            if 100 <= y < 128 and 24 <= x < 1000:
                row += red
            elif y == 76 and 24 <= x < 1000:
                row += ink
            elif 260 <= y < 420 and 24 <= x < 1000:
                # three empty top-story card outlines
                if x in (24, 341, 342, 658, 659, 999):
                    row += ink
                elif y in (260, 419):
                    row += ink
                elif 261 <= y < 317:
                    row += navy
                else:
                    row += paper
            else:
                row += paper
        rows.append(bytes(row))
    raw = b"".join(rows)
    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n"
    png += _png_chunk(b"IHDR", ihdr)
    png += _png_chunk(b"IDAT", zlib.compress(raw, 9))
    png += _png_chunk(b"IEND", b"")
    return png


def _resolve_output_dir():
    env_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if env_dir:
        return env_dir
    if os.path.isdir("/output"):
        return "/output"
    return os.path.dirname(os.path.abspath(__file__))


def main():
    out_dir = _resolve_output_dir()
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError:
        out_dir = os.path.dirname(os.path.abspath(__file__))
        os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    try:
        data = base64.b64decode(IMAGE_B64, validate=True)
        if not data.startswith(b"\x89PNG\r\n\x1a\n"):
            raise binascii.Error("embedded data is not a PNG")
    except (binascii.Error, ValueError):
        data = _fallback_png()
    with open(out_path, "wb") as fh:
        fh.write(data)
    print("wrote %s (%d bytes)" % (out_path, len(data)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
